-- A migration applied by hand (SQL editor) is not recorded above, so also check the
-- columns the most recent migrations add. Every row should say present = true.
SELECT t.tbl, t.col,
       EXISTS (SELECT 1 FROM information_schema.columns c
               WHERE c.table_schema = 'public' AND c.table_name = t.tbl AND c.column_name = t.col) AS present
FROM (VALUES
  ('Visitor', 'exitNotMarked'),
  ('Villa', 'maintenanceExemptFromPeriod'),
  ('RefreshToken', 'rotatedAt'),
  ('PushDevice', 'deactivatedAt'),
  ('PushDevice', 'deactivatedReason'),
  ('Villa', 'maintenanceExemptReason')
) AS t(tbl, col);
